#!/usr/bin/env bash
# SPDX-License-Identifier: AGPL-3.0-only
#
# DEP-026: every first-party .go, .ts and .vue file starts with the SPDX
# identifier. Generated files (Go "Code generated … DO NOT EDIT", files written
# by openapi-typescript) and vendored/build output are excluded.
#
#   scripts/spdx.sh --check   list files without the header, exit 1 if any (CI)
#   scripts/spdx.sh --fix     add the header where missing (idempotent)
#
# Go/TS get "// SPDX-License-Identifier: AGPL-3.0-only" plus a blank line, so
# the header never merges into a package doc comment and may sit above
# //go:build. Vue gets an HTML comment (// is not valid outside <script>).
set -euo pipefail
MODE=${1:---check}
ID='SPDX-License-Identifier: AGPL-3.0-only'
cd "$(dirname "$0")/.."

files() {
  find . \( -path ./.git -o -path ./development -o -path '*/node_modules' -o -path ./web/dist \
            -o -path ./web/test-results -o -path ./web/playwright-report -o -path ./web/coverage \) -prune \
         -o -type f \( -name '*.go' -o -name '*.ts' -o -name '*.vue' \) -print | sort
}
generated() {
  head -n 5 "$1" | grep -qE 'Code generated .* DO NOT EDIT|auto-generated by openapi-typescript'
}
has_header() { head -n 3 "$1" | grep -q "$ID"; }

missing=()
while IFS= read -r f; do
  generated "$f" && continue
  has_header "$f" && continue
  missing+=("$f")
done < <(files)

if [ "$MODE" = --check ]; then
  if [ ${#missing[@]} -gt 0 ]; then
    printf 'missing SPDX header (%d):\n' "${#missing[@]}" >&2
    printf '  %s\n' "${missing[@]}" >&2
    echo "run scripts/spdx.sh --fix" >&2
    exit 1
  fi
  echo "ok: SPDX header present in every first-party .go/.ts/.vue file"
  exit 0
fi

[ "$MODE" = --fix ] || { echo "usage: $0 --check|--fix" >&2; exit 2; }
for f in ${missing[@]+"${missing[@]}"}; do
  tmp=$(mktemp)
  case $f in
    *.vue) { printf '<!-- %s -->\n' "$ID"; cat "$f"; } >"$tmp" ;;
    *)     { printf '// %s\n\n' "$ID"; cat "$f"; } >"$tmp" ;;
  esac
  cat "$tmp" >"$f" && rm -f "$tmp"
done
echo "added SPDX header to ${#missing[@]} file(s)"
